document.addEventListener("DOMContentLoaded",()=>{const logoutLink=document.getElementById("logout-link");if(logoutLink){logoutLink.addEventListener("click",async e=>{e.preventDefault();await Auth.logout();window.location.href="login.html"})}const badge=document.getElementById("nav-messages-badge");const token=Auth.getToken();if(badge&&token){Api.post("getUnreadCount",{token:token}).then(res=>{if(res.ok&&res.unreadCount>0){badge.textContent=res.unreadCount;badge.classList.remove("hidden")}})}});